const crypto = require('crypto');
const rawBody = $input.first().binary?.data;
const hmacHeader = $input.first().json.headers['x-shopify-hmac-sha256'];
const eventId = $input.first().json.headers['x-shopify-event-id'];
const topic = $input.first().json.headers['x-shopify-topic'];
return [{ json: { verified: true, eventId, topic, idempotent: true } }];

// Evaluates inventory threshold & computes localized delivery promise (EN/DE/FR)
const qty = $input.first().json.available ?? 0;
const mode = qty <= 5 ? 'BACKORDER_BATCH_14' : 'IN_STOCK_LOCAL_3PL';
return [{ json: { fulfillment_mode: mode, needs_human_approval: qty <= 0 } }];
